import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len && buffer[ptr] <= ' ') ptr++;
            if (ptr == len) {
                len = in.read(buffer);
                ptr = 0;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        long[] positions = new long[n];
        long total = 0;

        for (int i = 0; i < n; i++) {
            positions[i] = total;
            total += fs.nextInt();
        }

        if ((total & 1L) != 0) {
            System.out.println("N");
            return;
        }

        long half = total / 2;
        HashSet<Long> set = new HashSet<>(n * 2);
        for (long position : positions) set.add(position);

        int pairs = 0;
        for (long position : positions) {
            if (position < half && set.contains(position + half)) {
                pairs++;
                if (pairs >= 2) {
                    System.out.println("S");
                    return;
                }
            }
        }

        System.out.println("N");
    }
}
